13		PlanStatusOpen     = "未完成"
14		PlanStatusDone     = "已完成"
15		PlanStatusCanceled = "已取消"
16	)
17	
18	// 待办相对本机今天的标记。
19	const (
20		TodoToday   = "今天需校准"
21		TodoOverdue = "逾期"
22		TodoFuture  = "未到计划日"
23	)
