645		}
646		human := fmt.Sprintf("%s：计划 %s，证书 %s，完成时间 %s。\n",
647			note, p.Number, p.CertificateNumber, p.CompletedAt)
648		return emit(opts, stdout, stderr, human,
649			map[string]any{"accepted": true, "idempotent": idempotent, "plan": p})
650	}
651	
652	func cmdTodos(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
653		fs := newFlagSet("todos", &opts)
654		instrument := fs.String("instrument", "", "只看该器具编号的待办")
655		if err := fs.Parse(args); err != nil {
656			fmt.Fprintln(stderr, "todos 参数错误：", err)
657			return 2
658		}
659		items, err := l.Todos(*instrument)
660		if err != nil {
661			if errors.Is(err, calibrate.ErrNotFound) {
662				return failBusiness(opts, stdout, stderr, err,
663					map[string]any{"found": false, "error": err.Error()})
664			}
665			return failIO(stderr, err)
666		}
667		var sb strings.Builder
668		if len(items) == 0 {
669			sb.WriteString("无待办。\n")
670		}
671		for _, it := range items {
672			fmt.Fprintf(&sb, "%s\t%s（%s，%s）\t%s\t%s\t%s\n",
673				it.PlanNumber, it.InstrumentID, it.InstrumentName, it.Status,
674				it.PlannedDate, it.Marker, it.Note)
675		}
676		return emit(opts, stdout, stderr, sb.String(),
677			map[string]any{"todos": items, "count": len(items)})
678	}
