385			t.Fatalf("应拒绝且 recorded=false，code=%d stdout=%q", r.code, r.stdout)
386		}
387		if got := readUsageCount(t, b); got != before {
388			t.Fatalf("目标文件被写入了使用记录：%d -> %d", before, got)
389		}
390	}
