506			}
507		}
508	
509		// 按器具核对的 JSON 结果中完整查到这些文字；退出后重开同一台账保持一致。
510		want := map[string][2]string{
511			"C-1": {"比较法", "--json"},
512			"C-2": {"-f备用.json", "例行"},
513			"C-3": {"--file=另一本.json", "等号形式"},
514		}
515		for i := 0; i < 2; i++ {
516			rv := runArgs(t, "review", "--id", "M-1", "-f", target, "--json")
517			if rv.code != 0 {
518				t.Fatalf("review 失败 code=%d stderr=%s", rv.code, rv.stderr)
519			}
520			var view struct {
521				History []struct {
522					Number  string `json:"number"`
523					Method  string `json:"method"`
524					Summary string `json:"summary"`
525				} `json:"history"`
526			}
527			if err := json.Unmarshal([]byte(rv.stdout), &view); err != nil {
528				t.Fatalf("review JSON 解析失败: %v\n%s", err, rv.stdout)
529			}
530			got := map[string][2]string{}
531			for _, h := range view.History {
532				got[h.Number] = [2]string{h.Method, h.Summary}
533			}
534			for number, ms := range want {
535				if got[number] != ms {
536					t.Fatalf("第 %d 次核对 %s 内容不符：got=%v want=%v", i+1, number, got[number], ms)
537				}
538			}
539		}
540	}
541	
