// save 把当前台账完整写回文件：先写临时文件再原子改名，
// 保证无效录入中断时不会留下半份记录。
func (l *Ledger) save() error {
	if err := os.MkdirAll(filepath.Dir(l.path), 0o755); err != nil {
		return fmt.Errorf("写入台账文件 %s 前创建目录失败: %w", l.path, err)
	}
