	prev, err := cloneData(l.data)
	if err != nil {
		return saveError(fmt.Sprintf("备份台账 %s 的当前内容: %v", l.path, err), err)
	}
	fn()
	if err := l.save(); err != nil {
		l.data = prev
		return err
	}
	return nil
}

